// Write a grep-attribution workload to a file (runner helper). Generates the
// exact same bytes as grep_attribution_bench's in-memory stages, so CLI/rg/
// GNU grep comparisons scan identical data.
//
//   grep_workload_gen <name> <out-path> [--bytes N] [--pattern S]
//   grep_workload_gen --print-pattern <name> [--bytes N]
//
// `name` is a workload from the matrix. --pattern OVERRIDES the embedded
// pattern (density stays the workload's), but the generated BYTES then
// differ from the named workload's canonical bytes: the PRNG draw sequence
// in grep_workloads.hpp depends on the pattern (occurrence draws and offset
// ranges), so an override is a DIFFERENT workload, not the same bytes with
// a different needle. --print-pattern prints the named workload's embedded
// pattern so callers (the runner) reuse the single source of truth instead
// of duplicating it. Unknown flags, unknown names, or a flag missing its
// value exit 2.
#include "grep_workloads.hpp"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <limits>
#include <string>
#include <string_view>

namespace {

int usage(const char* argv0, const char* detail) {
    std::fprintf(stderr,
                 "usage: %s <workload-name> <out-path> [--bytes N] "
                 "[--pattern S]\n"
                 "       %s --print-pattern <workload-name> [--bytes N]\n"
                 "error: %s\n",
                 argv0, argv0, detail);
    return 2;
}

// Whole-number decimal parse: rejects empty text, trailing garbage, and
// overflow (strtoull would silently accept "5x" and wrap around).
bool parse_size(const char* s, std::size_t& out) {
    if (s == nullptr || *s == '\0') return false;
    std::size_t v = 0;
    const std::size_t limit = std::numeric_limits<std::size_t>::max();
    for (const char* p = s; *p != '\0'; ++p) {
        if (*p < '0' || *p > '9') return false;
        unsigned d = static_cast<unsigned>(*p - '0');
        if (v > (limit - d) / 10) return false;
        v = v * 10 + d;
    }
    out = v;
    return true;
}

}  // namespace

int main(int argc, char** argv) {
    std::string name;
    std::string out_path;
    std::size_t bytes = 64ULL << 20;
    bool override_pat = false;
    bool print_pattern = false;
    bool have_name = false;
    bool have_out = false;
    std::string pattern;

    for (int i = 1; i < argc; ++i) {
        std::string_view a = argv[i];
        if (a == "--print-pattern") {
            print_pattern = true;
        } else if (a == "--bytes") {
            if (i + 1 >= argc) return usage(argv[0], "--bytes requires a value");
            if (!parse_size(argv[++i], bytes) || bytes < 1)
                return usage(argv[0], "--bytes: invalid/zero number");
        } else if (a == "--pattern") {
            if (i + 1 >= argc)
                return usage(argv[0], "--pattern requires a value");
            pattern = argv[++i];
            override_pat = true;
        } else if (!a.empty() && a[0] == '-') {
            return usage(argv[0], "unknown flag");
        } else if (!have_name) {
            name = argv[i];
            have_name = true;
        } else if (!print_pattern && !have_out) {
            out_path = argv[i];
            have_out = true;
        } else {
            return usage(argv[0], "unexpected argument");
        }
    }
    if (!have_name) return usage(argv[0], "missing workload name");
    if (!print_pattern && !have_out)
        return usage(argv[0], "missing out-path");
    if (print_pattern && override_pat)
        return usage(argv[0], "--print-pattern prints the embedded pattern; "
                             "--pattern override is meaningless with it");

    auto wls = sluice::bench::grep_wl::matrix(bytes);
    for (auto& w : wls) {
        if (w.name != name) continue;
        if (print_pattern) {
            std::fwrite(w.pattern.data(), 1, w.pattern.size(), stdout);
            std::fputc('\n', stdout);
            return 0;
        }
        if (override_pat) w.pattern = pattern;
        std::string data = sluice::bench::grep_wl::generate(w);
        std::ofstream f(out_path, std::ios::binary | std::ios::trunc);
        if (!f) {
            std::fprintf(stderr, "cannot open %s\n", out_path.c_str());
            return 2;
        }
        f.write(data.data(), static_cast<std::streamsize>(data.size()));
        if (!f) {
            std::fprintf(stderr, "write failed: %s\n", out_path.c_str());
            return 2;
        }
        // Explicit close with a state check: the destructor's implicit
        // close cannot report a flush failure, and a silently truncated
        // workload file would corrupt every measurement that reads it.
        f.close();
        if (!f) {
            std::fprintf(stderr, "close/flush failed: %s\n",
                         out_path.c_str());
            return 2;
        }
        return 0;
    }
    std::fprintf(stderr, "unknown workload: %s\n", name.c_str());
    return 2;
}
